52	  // Utility method to merge two sketches
53	  private Sketch<IntegerSummary> union(Sketch<IntegerSummary> a, Sketch<IntegerSummary> b) {
54	    return new Union<>(new IntegerSummarySetOperations(_mode, _mode)).union(a, b);
55	  }
56	
57	  @Override
58	  public Sketch<IntegerSummary> getInitialAggregatedValue(byte[] rawValue) {
59	    Sketch<IntegerSummary> initialValue = deserializeAggregatedValue(rawValue);
